/* Place search + boundary highlight — shared by the Satellite (map.html) and plain
 * Map (plain.html) views. Design: docs/superpowers/specs/2026-07-19-place-search-and-plain-map-design.md
 *
 * The search index (data/geo/places.json — towns/suburbs/municipalities + bboxes,
 * generated by the data repo's extract/export_places.py) is lazy-loaded on first
 * focus. Selecting a place flies the map to its bbox IMMEDIATELY, then live-fetches
 * the boundary polygon from the StatsSA census-boundaries service (same
 * gis.westerncape.gov.za host as the cadastre) and renders it as a translucent
 * highlight. Municipality boundaries come from the committed
 * data/geo/wc-municipalities.geojson — no network fetch for those.
 * Degrades quietly (DATA_CONTRACT §14): polygon fetch failure keeps the fly-to and
 * shows a hint; index fetch failure shows an honest "unavailable" row.
 * No symbol/text label layer on the highlight: the satellite style has no glyphs
 * URL configured, so text would silently not render — the name lives in the input. */

const BOUNDARY_SVC = 'https://gis.westerncape.gov.za/server2/rest/services/SpatialDataWarehouse/StatsSA_CensusBoundaries/MapServer';
const TOWN_LAYER = 3, SUBURB_LAYER = 1;
const EMPTY_FC = { type: 'FeatureCollection', features: [] };
const cssVar = n => getComputedStyle(document.documentElement).getPropertyValue(n).trim();
const esc = s => String(s ?? '').replace(/[&<>"']/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));

// Diacritic/punctuation-insensitive matching ("Wüpperthal", "Betty's Bay") —
// deliberately stronger than atlas.js's norm(), which place names need.
const norm = s => (s || '').normalize('NFD').replace(/[\u0300-\u036f]/g, '')
  .toLowerCase().replace(/[^a-z0-9]/g, '');

/* ─────────────────────────── index (lazy, memoized) ─────────────────────────── */

let placeIndex = null, indexPromise = null;
function loadIndex() {
  if (!indexPromise) {
    indexPromise = fetch('data/geo/places.json?v=1')
      .then(r => { if (!r.ok) throw new Error('HTTP ' + r.status); return r.json(); })
      .catch(e => { console.warn('places index unavailable', e); return null; })
      .then(a => (placeIndex = a));
  }
  return indexPromise;
}

// Rank: exact > prefix > substring; towns/municipalities before suburbs at equal
// match quality (so "Hermanus" the town outranks "Hermanus" the suburb).
function filterPlaces(q, limit = 8) {
  const nq = norm(q);
  if (!nq || !placeIndex) return [];
  const scored = [];
  for (const e of placeIndex) {
    const n = e._n || (e._n = norm(e.name));
    let s = n === nq ? 0 : n.startsWith(nq) ? 1 : n.includes(nq) ? 2 : -1;
    if (s < 0) continue;
    scored.push([s * 2 + (e.type === 'suburb' ? 1 : 0), e]);
  }
  scored.sort((a, b) => a[0] - b[0] ||
    a[1].name.length - b[1].name.length || a[1].name.localeCompare(b[1].name));
  return scored.slice(0, limit).map(x => x[1]);
}

/* ─────────────────────── boundary fetch (live, cached) ─────────────────────── */

const boundaryCache = new Map();
let muniGeoPromise = null, hlAbort = null;

const placeKey = e =>
  e.type === 'town' ? 't' + e.mp :
  e.type === 'suburb' ? 's' + e.sp.join('_') : 'm' + norm(e.name);

async function fetchBoundary(entry, signal) {
  const key = placeKey(entry);
  if (boundaryCache.has(key)) return boundaryCache.get(key);
  let fc;
  if (entry.type === 'municipality') {
    // same URL addBoundaries() already fetched → served from the HTTP cache
    if (!muniGeoPromise) muniGeoPromise = fetch('data/geo/wc-municipalities.geojson').then(r => r.json());
    const gj = await muniGeoPromise;
    const f = gj.features.find(f => f.properties.name === entry.name);
    if (!f) throw new Error('municipality not in geojson: ' + entry.name);
    fc = { type: 'FeatureCollection', features: [f] };
  } else {
    const layer = entry.type === 'town' ? TOWN_LAYER : SUBURB_LAYER;
    const where = entry.type === 'town'
      ? `MP_CODE=${entry.mp}`
      : `SP_CODE IN (${entry.sp.join(',')})`;
    const params = new URLSearchParams({
      where, outFields: '', returnGeometry: 'true',
      f: 'geojson', outSR: '4326', geometryPrecision: '5',
    });
    const res = await fetch(`${BOUNDARY_SVC}/${layer}/query?${params}`, { signal });
    fc = await res.json();
    if (!fc.features || !fc.features.length) throw new Error('no boundary features');
  }
  boundaryCache.set(key, fc);
  return fc;
}

/* ───────────────────────────── highlight layers ───────────────────────────── */

function addPlaceHighlightLayer(map, beforeId) {
  map.addSource('place-hl', { type: 'geojson', data: EMPTY_FC,
    attribution: 'Place boundaries: Stats SA Census / Western Cape Government' });
  map.addLayer({
    id: 'place-hl-fill', type: 'fill', source: 'place-hl',
    paint: {
      'fill-color': cssVar('--map-parcel-sel'),
      // fade as parcels take over the story at close zoom
      'fill-opacity': ['interpolate', ['linear'], ['zoom'], 6, 0.28, 13, 0.18, 16.5, 0.07],
    },
  }, beforeId);
  map.addLayer({
    id: 'place-hl-line', type: 'line', source: 'place-hl',
    paint: {
      'line-color': cssVar('--map-parcel-sel'),
      'line-width': ['interpolate', ['linear'], ['zoom'], 6, 1.6, 13, 2.4, 18, 3],
    },
  }, beforeId);
}

const showHighlight = (map, fc) => map.getSource('place-hl').setData(fc);
const clearHighlight = map => map.getSource('place-hl').setData(EMPTY_FC);

/* ──────────────────────────────── search UI ──────────────────────────────── */

// Single entry point — map.js calls this on map 'load' with its i18n + hint helpers.
export function initPlaceSearch(map, { t, setHint, beforeId }) {
  const input = document.getElementById('placeSearch');
  const listbox = document.getElementById('placeResults');
  const clearBtn = document.getElementById('placeClear');
  const wrap = document.getElementById('searchWrap');
  if (!input || !listbox || !clearBtn || !wrap) return;

  addPlaceHighlightLayer(map, beforeId);

  let rows = [], active = -1, debounce = null;

  const typeLabel = e =>
    e.type === 'town' ? t('Town') : e.type === 'suburb' ? t('Suburb') : t('Municipality');
  const context = e =>
    e.type === 'suburb' ? [e.town !== e.name ? e.town : null, e.muni].filter(Boolean).join(' · ')
    : e.type === 'town' ? e.muni : '';

  function close() {
    listbox.hidden = true; input.setAttribute('aria-expanded', 'false');
    active = -1; input.removeAttribute('aria-activedescendant');
  }

  function render() {
    if (!rows.length) {
      listbox.innerHTML = `<div class="sEmpty">${placeIndex === null && indexPromise
        ? t('Search unavailable right now') : t('No matches')}</div>`;
    } else {
      listbox.innerHTML = rows.map((e, i) =>
        `<div class="sRow" id="sopt-${i}" role="option" aria-selected="${i === active}">` +
        `<span class="sName">${esc(e.name)}</span>` +
        `<span class="sCtx">${esc([typeLabel(e), context(e)].filter(Boolean).join(' · '))}</span></div>`
      ).join('');
      listbox.querySelectorAll('.sRow').forEach(el => {
        // mousedown, not click: fires before the input's blur hides the list
        el.addEventListener('mousedown', ev => { ev.preventDefault(); select(rows[+el.id.slice(5)]); });
      });
    }
    listbox.hidden = false;
    input.setAttribute('aria-expanded', 'true');
  }

  function setActive(i) {
    active = i;
    listbox.querySelectorAll('.sRow').forEach((el, j) => {
      el.setAttribute('aria-selected', String(j === i));
      if (j === i) { el.scrollIntoView({ block: 'nearest' }); input.setAttribute('aria-activedescendant', el.id); }
    });
  }

  async function search() {
    await loadIndex();
    const q = input.value.trim();
    if (q.length < 2) { close(); return; }
    rows = filterPlaces(q);
    render();
  }

  async function select(entry) {
    close();
    input.value = entry.name;
    input.blur();
    clearBtn.hidden = false;
    const [w, s, e, n] = entry.bbox;
    map.fitBounds([[w, s], [e, n]],
      { padding: 70, maxZoom: entry.type === 'municipality' ? 11 : 16, duration: 900 });
    history.replaceState(null, '', '#p/' + placeKey(entry));
    syncViewLinks();
    if (hlAbort) hlAbort.abort();
    const ctl = (hlAbort = new AbortController());
    try {
      const fc = await fetchBoundary(entry, ctl.signal);
      if (ctl.signal.aborted) return;
      showHighlight(map, fc);
    } catch (err) {
      if (err.name === 'AbortError') return;
      console.warn('boundary fetch failed', err);
      setHint(t('Boundary unavailable — zoomed to the area'));   // fly-to already happened
    }
  }

  function clearAll() {
    input.value = '';
    clearBtn.hidden = true;
    clearHighlight(map);
    close();
    history.replaceState(null, '', location.pathname + location.search);
    syncViewLinks();
  }

  // keep the Satellite↔Map view links carrying the selected place across a switch
  function syncViewLinks() {
    document.querySelectorAll('.viewseg a[href^="map.html"], .viewseg a[href^="plain.html"]')
      .forEach(a => { a.href = a.href.split('#')[0] + location.hash; });
  }

  input.addEventListener('input', () => {
    clearTimeout(debounce);
    debounce = setTimeout(search, 150);
    if (!input.value) { clearBtn.hidden = true; clearHighlight(map); }
  });
  input.addEventListener('focus', () => { loadIndex(); if (input.value.trim().length >= 2) search(); });
  input.addEventListener('keydown', ev => {
    if (ev.key === 'Escape') { close(); input.blur(); ev.stopPropagation(); return; }
    if (listbox.hidden || !rows.length) return;
    if (ev.key === 'ArrowDown') { ev.preventDefault(); setActive(Math.min(active + 1, rows.length - 1)); }
    else if (ev.key === 'ArrowUp') { ev.preventDefault(); setActive(Math.max(active - 1, 0)); }
    else if (ev.key === 'Enter') { ev.preventDefault(); select(rows[active >= 0 ? active : 0]); }
  });
  clearBtn.addEventListener('click', clearAll);
  // the whole glass platter reads as the field — clicking any of it focuses the input
  wrap.addEventListener('click', ev => { if (ev.target === wrap || ev.target.closest('svg')) input.focus(); });
  document.addEventListener('mousedown', ev => { if (!wrap.contains(ev.target)) close(); });

  // deep link: #p/t<mp> | #p/s<sp[_sp…]> | #p/m<normname>
  const deep = location.hash.match(/^#p\/([tsm].+)$/);
  if (deep) {
    loadIndex().then(() => {
      if (!placeIndex) return;
      const entry = placeIndex.find(e => placeKey(e) === deep[1]);
      if (entry) select(entry);
    });
  }
}
